const body = $json.body ?? $json;
const job = body.job || body.job_name || `job-${Date.now()}`;
const payload = JSON.stringify({
  job,
  pull: body.pull === true || body.pull === 'true' || body.pull === 1,
  push: body.push === true || body.push === 'true' || body.push === 1,
  lang: body.lang || 'deu+eng',
  threshold: body.threshold ?? 85,
  limit: body.limit ?? 0,
  no_mistral: body.no_mistral === true,
  skip_preprocess: body.skip_preprocess === true || body.skip_preprocess === 'true' || body.skip_preprocess === 1,
  container: body.container || 'alexandria_worker',
  scripts_path: body.scripts_path || '/opt/alexandria/scripts',
});
const escaped = payload.replace(/'/g, `'\\''`);
const command = `/opt/alexandria/scripts/n8n_run_job.sh '${escaped}'`;
return [{ json: { job, payload: JSON.parse(payload), command, request: body } }];

const raw = $json.stdout || $json.data || '';
let report = null;
try {
  const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const m = text.match(/\{[\s\S]*"job"\s*:[\s\S]*\}/);
  if (m) {
    report = JSON.parse(m[0]);
  } else {
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start >= 0 && end > start) report = JSON.parse(text.slice(start, end + 1));
  }
} catch (e) {
  report = { parse_error: String(e), raw };
}
const prep = $('Build docker exec command').item.json;
const ok = !!(report && !report.parse_error && !report.error);
return [{
  json: {
    ok,
    job: prep.job,
    command: prep.command,
    report,
    exitCode: $json.exitCode ?? null
  }
}];
